use ratatui::{backend::CrosstermBackend,widgets::{Block,Borders,Gauge,Paragraph},layout::{Layout,Constraint,Direction},Terminal}; use crossterm::{execute,terminal::{enable_raw_mode,disable_raw_mode},event::{self,Event,KeyCode}}; use std::io;
fn main()->Result<(),Box<dyn std::error::Error>>{enable_raw_mode()?;let mut out=io::stdout();execute!(out,crossterm::terminal::EnterAlternateScreen)?;let mut t=Terminal::new(CrosstermBackend::new(out))?;let mut p=0;loop{t.draw(|f|{let a=Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3),Constraint::Length(3),Constraint::Min(1)].as_ref()).split(f.area());f.render_widget(Gauge::default().block(Block::default().title("Overall Progress").borders(Borders::ALL)).percent(p),a[0]);f.render_widget(Paragraph::new("Chimera Email Extractor — public/authorized web crawling\nPress Enter to start; q to quit"),a[1]);f.render_widget(Block::default().title("Results").borders(Borders::ALL),a[2]);})?;if event::poll(std::time::Duration::from_millis(100))?{if let Event::Key(k)=event::read()?{match k.code{KeyCode::Char('q')=>break,KeyCode::Enter=>{p=100;},_=>{}}}}}disable_raw_mode()?;execute!(t.backend_mut(),crossterm::terminal::LeaveAlternateScreen)?;Ok(())}
